import json
from itertools import permutations

def compute_itinerary():
    # Input variables
    total_days = 19
    required_days = {
        "Dubrovnik": 5,
        "Warsaw": 2,
        "Stuttgart": 7,
        "Bucharest": 6,
        "Copenhagen": 3
    }

    # Direct flight connections (undirected)
    direct_flights = {
        "Warsaw": {"Copenhagen", "Stuttgart", "Bucharest"},
        "Copenhagen": {"Warsaw", "Stuttgart", "Bucharest", "Dubrovnik"},
        "Stuttgart": {"Copenhagen", "Warsaw"},
        "Bucharest": {"Copenhagen", "Warsaw"},
        "Dubrovnik": {"Copenhagen"}
    }

    # Constraints
    conference_city = "Stuttgart"
    conference_days = {7, 13}
    wedding_city = "Bucharest"
    wedding_window = (1, 6)  # inclusive

    cities = list(required_days.keys())
    n = len(cities)

    # Feasibility quick check: sum of required days must equal total_days + (number of flights)
    # With contiguous blocks and counting overlap on flight days, flights = n-1
    if sum(required_days.values()) != total_days + (n - 1):
        return {"itinerary": [], "note": "No feasible solution due to inconsistent day totals."}

    def is_adjacent_path(order):
        for i in range(1, len(order)):
            if order[i] not in direct_flights.get(order[i-1], set()):
                return False
        return True

    def build_intervals(order):
        # Returns dict city -> (start_day, end_day) using overlap rule on flight days
        intervals = {}
        # First city
        prev_end = required_days[order[0]]  # t2
        intervals[order[0]] = (1, prev_end)
        # Middle cities
        for i in range(1, n - 1):
            city = order[i]
            start = prev_end
            end = start + required_days[city] - 1
            intervals[city] = (start, end)
            prev_end = end
        # Last city
        city = order[-1]
        start = prev_end
        end = total_days
        intervals[city] = (start, end)
        return intervals

    def valid_constraints(intervals):
        # Conference days in Stuttgart
        if conference_city not in intervals:
            return False
        s_start, s_end = intervals[conference_city]
        if not all(s_start <= d <= s_end for d in conference_days):
            return False
        # Wedding window: must be in Bucharest on at least one day between day 1 and 6 inclusive
        if wedding_city not in intervals:
            return False
        w_start, w_end = intervals[wedding_city]
        a, b = wedding_window
        if max(w_start, a) > min(w_end, b):
            return False
        # Verify each city's interval length matches required days
        for city, (st, en) in intervals.items():
            if en - st + 1 != required_days[city]:
                return False
        # Verify last city's end matches total_days
        if max(en for _, en in intervals.items()) != total_days:
            return False
        return True

    def cost_function(intervals):
        # Prefer aligning Stuttgart exactly with days 7-13 and Bucharest with days 1-6
        c = 0
        if conference_city in intervals:
            s_start, s_end = intervals[conference_city]
            c += abs(s_start - 7) + abs(s_end - 13)
        if wedding_city in intervals:
            b_start, b_end = intervals[wedding_city]
            c += abs(b_start - 1) + abs(b_end - 6)
        return c

    best = None
    best_cost = None
    best_key = None  # tiebreaker

    for order in permutations(cities):
        if not is_adjacent_path(order):
            continue
        intervals = build_intervals(order)
        if not valid_constraints(intervals):
            continue
        cost = cost_function(intervals)
        # Tiebreaker by order and intervals for determinism
        key = (order, tuple((city, intervals[city]) for city in order))
        if best is None or cost < best_cost or (cost == best_cost and key < best_key):
            best = (order, intervals)
            best_cost = cost
            best_key = key

    if best is None:
        return {"itinerary": [], "note": "No feasible itinerary found under given constraints."}

    order, intervals = best
    itinerary = []
    for city in order:
        st, en = intervals[city]
        itinerary.append({"day_range": f"Day {st}-{en}", "place": city})
    return {"itinerary": itinerary}

if __name__ == "__main__":
    result = compute_itinerary()
    print(json.dumps(result, ensure_ascii=False))
